def followup_view(inputs, prior):
    packet=inputs.get('seventh_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('period packet changed')
    if prior is None or prior['counts']['after']!=70 or packet['prior_digest']!=digest(prior):raise ValueError('period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=18 or len(packet['sources'])!=18 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid] or not s['protected_gate_passed']:raise ValueError('period source binding changed')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)} or len(s['page_hashes'])!=s['pages']:raise ValueError('period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('period page changed')
    for metric in H1_METRICS:
        actual=((D(metric['current_yuan'])-D(metric['prior_yuan']))/abs(D(metric['prior_yuan']))*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if actual!=D(metric['reported_pct']):raise ValueError('period H1 arithmetic changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()))
    return {'through':'2026-11-19','title':'解冻、和解、重组进展，哪些真的改变了判断？','answer':'棕榈的一户解冻不代表全部资金恢复可用，两份和解还要分清谁收款、谁付款；利源月度重组公告仍未跨过正式协议。百灵与雪发的半年经营也有不同方向，不能用一个改善数字概括全部。','chains':CHAINS,'h1_metrics':H1_METRICS,'event_windows':windows,'sources':[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()],'counts':{'files':18,'pages':73,'viewed_pages':len(VISUAL),'initial_coverage':70,'complete_windows':sum(w['status']=='complete'for e in windows for w in e['windows']),'unfinished_windows':sum(w['status']=='unfinished'for e in windows for w in e['windows'])},'boundary':'仅支持所选正文与明确时点；73页中视觉核36关键页，未逐页审阅全部附件。期初覆盖保持70/150、仍缺80，完整官方历史名单及全部期间催化尚未认证。公告日前一市场日收盘为基准，不认证最早反应或净因果；单案和解与解冻不关闭其他约束，重复月度披露不增加经验验证次数。','method_promotions':0}
